create extension if not exists pgcrypto;

create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, role text not null default 'user' check (role in ('user','admin')), status text not null default 'active' check (status in ('active','suspended')), created_at timestamptz not null default now());
create table if not exists public.access_applications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, status text not null default 'pending' check (status in ('pending','approved','rejected')), submitted_at timestamptz not null default now(), reviewed_at timestamptz, reviewed_by uuid references public.profiles(id), review_note text);
create table if not exists public.entitlements (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, application_id uuid references public.access_applications(id), status text not null default 'active' check (status in ('active','expired','suspended')), approved_at timestamptz not null, expires_at timestamptz not null, quota_total_cents integer not null default 600 check (quota_total_cents = 600), quota_used_cents integer not null default 0, quota_remaining_cents integer not null default 600, approved_by uuid references public.profiles(id));
create table if not exists public.drafts (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null, language text not null check (language in ('zh','en')), content jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.usage_ledger (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), entitlement_id uuid not null references public.entitlements(id), request_id text not null unique, provider text not null, model text not null, input_tokens integer, output_tokens integer, total_tokens integer, estimated_cost_cents integer not null default 0, status text not null check (status in ('completed','failed','refunded','rejected')), created_at timestamptz not null default now());
create table if not exists public.quota_reservations (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), entitlement_id uuid not null references public.entitlements(id), request_id text not null unique, reserved_cents integer not null, settled_cents integer not null default 0, status text not null check (status in ('reserved','settled','refunded')), expires_at timestamptz not null, created_at timestamptz not null default now());

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id,email) values (new.id, new.email); insert into public.access_applications(user_id) values (new.id); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

create or replace function public.approve_application(p_application_id uuid, p_admin_id uuid) returns public.entitlements language plpgsql security definer set search_path = public as $$ declare result public.entitlements; begin if not exists (select 1 from public.profiles where id=p_admin_id and role='admin' and status='active') then raise exception 'not admin'; end if; update public.access_applications set status='approved', reviewed_at=now(), reviewed_by=p_admin_id where id=p_application_id and status='pending'; if not found then raise exception 'application unavailable'; end if; insert into public.entitlements(user_id,application_id,approved_at,expires_at,quota_total_cents,quota_remaining_cents,approved_by) select user_id,id,now(),now()+interval '30 days',600,600,p_admin_id from public.access_applications where id=p_application_id returning * into result; return result; end; $$;

create or replace function public.reserve_quota(p_user_id uuid, p_request_id text, p_amount integer) returns jsonb language plpgsql security definer set search_path = public as $$ declare e public.entitlements; begin if p_amount <= 0 or p_amount > 600 then raise exception 'invalid reservation'; end if; if exists (select 1 from public.quota_reservations where request_id=p_request_id) then return jsonb_build_object('request_id',p_request_id,'status','duplicate'); end if; update public.entitlements set quota_remaining_cents=quota_remaining_cents-p_amount where user_id=p_user_id and status='active' and expires_at>now() and quota_remaining_cents>=p_amount returning * into e; if not found then raise exception 'quota unavailable'; end if; insert into public.quota_reservations(user_id,entitlement_id,request_id,reserved_cents,expires_at) values(p_user_id,e.id,p_request_id,p_amount,now()+interval '10 minutes'); return jsonb_build_object('request_id',p_request_id,'entitlement_id',e.id,'status','reserved'); end; $$;

create or replace function public.settle_quota(p_user_id uuid, p_request_id text, p_provider text, p_model text, p_input_tokens integer, p_output_tokens integer, p_cost_cents integer) returns void language plpgsql security definer set search_path = public as $$ declare r public.quota_reservations; actual integer := greatest(0,p_cost_cents); begin select * into r from public.quota_reservations where request_id=p_request_id for update; if not found or r.user_id<>p_user_id or r.status<>'reserved' then raise exception 'reservation unavailable'; end if; if actual > r.reserved_cents then actual := r.reserved_cents; end if; update public.entitlements set quota_used_cents=quota_used_cents+actual, quota_remaining_cents=quota_remaining_cents+(r.reserved_cents-actual) where id=r.entitlement_id; update public.quota_reservations set status='settled',settled_cents=actual where id=r.id; insert into public.usage_ledger(user_id,entitlement_id,request_id,provider,model,input_tokens,output_tokens,total_tokens,estimated_cost_cents,status) values(p_user_id,r.entitlement_id,p_request_id,p_provider,p_model,p_input_tokens,p_output_tokens,coalesce(p_input_tokens,0)+coalesce(p_output_tokens,0),actual,'completed'); end; $$;

create or replace function public.refund_reservation(p_user_id uuid, p_request_id text, p_provider text default 'deepseek', p_model text default 'unknown') returns void language plpgsql security definer set search_path = public as $$ declare r public.quota_reservations; begin select * into r from public.quota_reservations where request_id=p_request_id for update; if not found or r.user_id<>p_user_id or r.status<>'reserved' then return; end if; update public.entitlements set quota_remaining_cents=quota_remaining_cents+r.reserved_cents where id=r.entitlement_id; update public.quota_reservations set status='refunded' where id=r.id; insert into public.usage_ledger(user_id,entitlement_id,request_id,provider,model,estimated_cost_cents,status) values(p_user_id,r.entitlement_id,p_request_id,p_provider,p_model,0,'failed'); end; $$;

alter table public.profiles enable row level security;
alter table public.access_applications enable row level security;
alter table public.entitlements enable row level security;
alter table public.drafts enable row level security;
alter table public.usage_ledger enable row level security;
alter table public.quota_reservations enable row level security;
create or replace function public.is_admin(p_user_id uuid) returns boolean language sql security definer set search_path = public stable as $$ select exists(select 1 from public.profiles where id=p_user_id and role='admin' and status='active'); $$;
create policy "users read own profile" on public.profiles for select using (auth.uid()=id or public.is_admin(auth.uid()));
create policy "users read own applications" on public.access_applications for select using (auth.uid()=user_id);
create policy "users submit own application" on public.access_applications for insert with check (auth.uid()=user_id);
create policy "users read own entitlement" on public.entitlements for select using (auth.uid()=user_id);
create policy "users manage own drafts" on public.drafts for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "users read own usage" on public.usage_ledger for select using (auth.uid()=user_id);
create policy "admins read applications" on public.access_applications for select using (public.is_admin(auth.uid()));
create policy "admins update applications" on public.access_applications for update using (public.is_admin(auth.uid())) with check (public.is_admin(auth.uid()));
create policy "admins read all entitlements" on public.entitlements for select using (public.is_admin(auth.uid()));
create policy "admins read all usage" on public.usage_ledger for select using (public.is_admin(auth.uid()));
grant execute on function public.approve_application(uuid,uuid) to authenticated;
grant execute on function public.reserve_quota(uuid,text,integer) to authenticated;
grant execute on function public.settle_quota(uuid,text,text,text,integer,integer,integer) to authenticated;
grant execute on function public.refund_reservation(uuid,text,text,text) to authenticated;
